  let lang = "fr";
  try {
    const q = new URLSearchParams(location.search).get("lang");
    if (q && SUPPORTED.includes(q)) localStorage.setItem("dtLang", q);
    lang = localStorage.getItem("dtLang") || "fr";
  } catch (e) {}
  if (!SUPPORTED.includes(lang)) lang = "fr";

